css:
#ui_ext_info {
  margin-bottom: 12px;
}

.ui-ext-note {
  background: #f3eafc;
  border: 1px solid #c9a7e8;
  border-left: 4px solid #7b3fa9;
  border-radius: 4px;
  padding: 10px 12px;
  color: #4a2168;
  font-size: 12px;
  line-height: 1.45;
  max-width: 900px;
}

.ui-ext-note p { margin: 0 0 8px; }
.ui-ext-note p:last-child { margin-bottom: 0; }
.ui-ext-note-title { font-weight: 600; }
.ui-ext-note-warn { font-style: italic; }
.ui-ext-note a { color: #7b3fa9; text-decoration: underline; }

#ci_picker { max-width: 900px; font-size: 13px; }

#ci_picker #ci_category { width: 100%; max-width: 460px; }

/* служебный виджет справочника — источник данных, пользователю не нужен */
#ci_picker #ci_source_row { display: none; }

/* технические поля расширения (значения уезжают в custom_data) */
#ci_picker .ci-tech { display: none; }

#ci_picker .ci-btn {
  display: inline-block; text-align: center; cursor: pointer;
  border-radius: 2px; padding: 7px 14px; font-weight: 600;
  line-height: 1; user-select: none; -webkit-user-select: none;
}
#ci_picker .ci-btn-primary { background: #1f7ae0; color: #fff; }
#ci_picker .ci-btn-primary:hover { background: #1666bd; }
#ci_picker .ci-disabled { background: #b9c6d4; cursor: default; }
#ci_picker .ci-disabled:hover { background: #b9c6d4; }

#ci_picker .ci-load { width: 100%; max-width: 460px; margin-bottom: 6px; }

#ci_picker .ci-status { color: #666; min-height: 16px; }
#ci_picker .ci-ok   { color: #17803d; }
#ci_picker .ci-warn { color: #b06a00; }
#ci_picker .ci-err  { color: #c0392b; }

#ci_picker .ci-cols {
  display: flex; align-items: flex-start; gap: 18px; margin-top: 12px;
}
#ci_picker .ci-col { flex: 1 1 0; min-width: 0; }
#ci_picker .ci-caption { margin-bottom: 4px; color: #333; }
#ci_picker .ci-count { color: #888; }

#ci_picker .ci-list {
  height: 200px; overflow-y: auto; background: #fff;
  border: 2px solid #333; border-radius: 2px; padding: 3px;
}
#ci_picker .ci-item {
  padding: 4px 6px; cursor: pointer; border-radius: 2px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
#ci_picker .ci-item:hover { background: #eef4fb; }
#ci_picker .ci-item.ci-sel { background: #1f7ae0; color: #fff; }

#ci_picker .ci-mid {
  display: flex; flex-direction: column; gap: 8px;
  align-self: center; padding-top: 18px;
}
#ci_picker .ci-arrow {
  width: 68px; background: #fff; color: #222;
  border: 1px solid #333; padding: 6px 0; font-weight: 700;
}
#ci_picker .ci-arrow:hover { background: #eef4fb; }

#ci_picker .ci-col-btns { margin-top: 10px; display: flex; gap: 14px; }
#ci_picker .ci-col-btns .ci-btn { flex: 1 1 0; }
#ci_picker .ci-col-btns-right { justify-content: flex-end; }
#ci_picker .ci-col-btns-right .ci-btn { flex: 0 0 auto; min-width: 60%; }

#ci_picker .ci-msg { margin-top: 10px; min-height: 18px; color: #666; }

@media (max-width: 720px) {
  #ci_picker .ci-cols { flex-direction: column; }
  #ci_picker .ci-mid { flex-direction: row; padding-top: 0; align-self: flex-start; }
}

javascript:
var $ = ITRP.$;            // jQuery
var $extension = $(this);  // The UI Extension container with custom HTML

/* ------------------------------------------------------------------
   Выбор КЕ пользователя запроса.

   ВСЯ ФИЛЬТРАЦИЯ — В ПРЕДСТАВЛЕНИИ (HTML):
     – категория продукта задана внутри представления;
     – пользователь приходит из #ci_user (data-filter-name="user").
   JS ничего не фильтрует. Он делает РОВНО ОДИН запрос к suggest-адресу
   выбранного справочника и раскладывает результат по двум спискам.

   Селект «Тип конфиг. единиц» выбирает, у какого из скрытых
   справочников (#ci_src_*) взять адрес — через data-source опции.

   «Загрузить» → «Доступные КЕ» → «>>» → «Добавить КЕ к запросу»
   ------------------------------------------------------------------ */
(function () {
  'use strict';

  var $ = ITRP.$;
  var LOG = '[ci_picker] ';

  var CFG = {
    reqField: 'req_cis',
    ciPath: '/cis/',
    pageSize: 200,      // КЕ одного человека в одну страницу влезают
    autoReload: true    // перезагружать список при смене типа КЕ
  };

  var $ext, $cat, $user, $av, $sel, $st, $msg;
  var pool = [];
  var pid = null;

  /* ---------------- утилиты ---------------- */

  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function status(text, kind) {
    $st.text(text || '').attr('class', 'ci-status' + (kind ? ' ci-' + kind : ''));
  }

  function message(text, kind) {
    $msg.text(text || '').attr('class', 'ci-msg' + (kind ? ' ci-' + kind : ''));
  }

  function counts() {
    $ext.find('.ci-count-av').text('(' + $av.find('.ci-item').length + ')');
    $ext.find('.ci-count-sel').text('(' + $sel.find('.ci-item').length + ')');
  }

  function itemHtml(id, name) {
    return '<div class="ci-item" data-id="' + esc(id) + '" title="' + esc(name) + '">' +
           esc(name) + '</div>';
  }

  function sortList($list) {
    var items = $list.find('.ci-item').get();
    items.sort(function (a, b) { return $(a).text().localeCompare($(b).text(), 'ru'); });
    $list.append(items);
  }

  function hardClick(el, fn) {
    if (!el) { return; }
    var handler = function (e) {
      e.preventDefault();
      e.stopPropagation();
      if (e.stopImmediatePropagation) { e.stopImmediatePropagation(); }
      fn();
      return false;
    };
    if (el.addEventListener) { el.addEventListener('click', handler, true); }
    $(el).on('click', handler);
  }

  /* ---------------- выбранный справочник ---------------- */

  function sourceId() {
    return $.trim($cat.find('option:selected').attr('data-source') || '');
  }

  function $src() {
    var id = sourceId();
    return id ? $ext.find('#' + id).first() : $();
  }

  function sourceView() {
    var $s = $src();
    return $s.length ? ($s.attr('data-custom-view') || '') : '';
  }

  /* ---------------- пользователь запроса ---------------- */

  function personId() {
    var v = null;
    var $i = $('#req_requested_for_id, #requested_for_id, input[name*="requested_for_id"]').first();
    if ($i.length) { v = $i.val(); }
    if (!v) {
      try {
        var f = ITRP.field('requested_for');
        if (f && f.val) { v = f.val(); }
      } catch (e) {}
      if (v && typeof v === 'object') { v = v.id; }
    }
    if (!v) {
      var $d = $('#requested_for').first();
      if ($d.length && $d.data('item')) { v = $d.data('item').id; }
    }
    if (!v) {
      var $a = $('#requested_for a[href*="/people/"]').first();
      var m = $a.length ? /\/people\/(\d+)/.exec($a.attr('href') || '') : null;
      if (m) { v = m[1]; }
    }
    return v ? String(v) : null;
  }

  function syncUser(keepList) {
    var id = personId();
    if (id === pid) { return false; }
    var first = (pid === null);
    pid = id;

    $user.val(id || '').trigger('change');

    status(id ? 'Пользователь запроса: #' + id + '. Нажмите «Загрузить».'
              : 'В запросе не заполнено поле «Запрошено для»', id ? '' : 'warn');
    console.log(LOG + 'requested_for = ' + id);

    if (!keepList && !first) {
      $sel.empty();
      syncFields();
      pool = [];
      $av.empty();
      counts();
      message('Пользователь изменился — нажмите «Загрузить»', 'warn');
    }
    return true;
  }

  function watchRequestedFor() {
    var fire = function () { setTimeout(function () { syncUser(); }, 0); };

    $(document).on(
      'change blur',
      '#req_requested_for_id, #requested_for_id, input[name*="requested_for_id"], ' +
      '#req_requested_for, #requested_for, #req_requested_for input, #requested_for input',
      fire
    );

    try {
      var f = ITRP.field('requested_for');
      if (f && f.on) { f.on('change', fire); }
    } catch (e) {}

    if (window.MutationObserver) {
      $.each(['req_requested_for', 'requested_for', 'req_requested_for_id', 'requested_for_id'],
        function (_, id) {
          var el = document.getElementById(id);
          if (!el) { return; }
          try {
            new MutationObserver(fire).observe(el.parentNode || el, {
              childList: true, subtree: true, characterData: true,
              attributes: true, attributeFilter: ['value', 'data-item', 'title']
            });
          } catch (e) {}
        });
    }
  }

  /* ---------------- нормализация ---------------- */

  function norm(row) {
    if (!row || row.id == null) { return null; }
    var meta = row.metadata || {};
    return {
      id: String(row.id),
      name: String(row.name || meta.name || row.label || ('КЕ #' + row.id)),
      url: row.url || (CFG.ciPath + row.id),
      statusLabel: row.status || null
    };
  }

  function setPool(rows) {
    var seen = {}, out = [];
    $.each(rows || [], function (_, r) {
      var c = norm(r);
      if (c && !seen[c.id]) { seen[c.id] = true; out.push(c); }
    });
    pool = out;
  }

  /* ---------------- ОДИН запрос ---------------- */

  function baseUrl() {
    var $s = $src();
    if (!$s.length) { return ''; }
    return $s.data('suggestUrl') || $s.data('suggest-url') || '';
  }

  function buildUrl() {
    var u = baseUrl();
    if (!u) { return null; }
    u = /[?&]q=/.test(u) ? u.replace(/([?&])q=[^&]*/, '$1q=')
                         : u + (u.indexOf('?') >= 0 ? '&' : '?') + 'q=';
    u += '&per_page=' + CFG.pageSize + '&limit=' + CFG.pageSize;
    u += '&uev_field_id=' + encodeURIComponent(sourceId()) +
         '&user=' + encodeURIComponent(pid);
    return u;
  }

  function load() {
    syncUser(true);
    $av.empty();
    pool = [];
    counts();

    if (!pid) { status('В запросе не заполнено поле «Запрошено для»', 'warn'); return; }
    if (!$src().length) {
      status('Для выбранного типа не задан справочник (data-source)', 'err');
      return;
    }
    if (!baseUrl()) { status('Справочник ещё не готов, попробуйте ещё раз', 'warn'); return; }

    var url = buildUrl();
    console.log(LOG + 'источник: ' + sourceId() + ' (' + sourceView() + ')');
    console.log(LOG + 'GET ' + url);
    status('Ищу КЕ пользователя…');

    $.ajax({ url: url, type: 'GET', dataType: 'json' })
      .done(function (data) {
        var rows = data;
        if (rows && !$.isArray(rows)) {
          rows = rows.records || rows.items || rows.results || rows.data || rows.suggestions || [];
        }
        if (!$.isArray(rows)) { rows = []; }

        console.log(LOG + 'получено записей: ' + rows.length);
        setPool(rows);
        render();
      })
      .fail(function (xhr) {
        console.error(LOG + 'запрос справочника упал', xhr && xhr.status);
        status('Не удалось загрузить справочник КЕ', 'err');
      });
  }

  /* ---------------- штатное поле req_cis ---------------- */

  function $req() {
    var $f = $('#' + CFG.reqField).not('#ci_picker *').first();
    if (!$f.length) { $f = $('[id$="' + CFG.reqField + '"]').not('#ci_picker *').first(); }
    return $f;
  }

  function $inner() {
    var $f = $req();
    var $d = $f.children('div').first();
    return $d.length ? $d : $f;
  }

  function $tracks() {
    var $in = $inner();
    var $t = $in.find('.tracks').first();
    if (!$t.length) {
      $t = $('<div class="tracks"></div>');
      var $link = $in.find('a.js-link-records').first();
      if ($link.length) { $link.before($t); } else { $in.prepend($t); }
    }
    return $t;
  }

  function $hidden() {
    var $in = $inner();
    var $h = $in.find('div.hide').first();
    if (!$h.length) {
      $h = $('<div class="hide"></div>');
      $in.append($h);
    }
    return $h;
  }

  function attachedIds() {
    var ids = {};
    $req().find('input[type=hidden]').each(function () {
      var v = $.trim($(this).val() || '');
      if (v) { ids[v] = true; }
    });
    return ids;
  }

  function ciInputName() {
    var name = $req().find('input[type=hidden]').first().attr('name');
    return name || 'req[ci_ids][]';
  }

  function syncTotal() {
    var $f = $req();
    var n = 0;
    $f.find('input[type=hidden]').each(function () {
      if ($.trim($(this).val() || '')) { n++; }
    });
    $f.attr('data-total', n).data('total', n);
  }

  function attachRows(recs) {
    var $f = $req();
    if (!$f.length) { return { ok: false, how: 'поле #' + CFG.reqField + ' не найдено' }; }

    var name = ciInputName();
    var have = attachedIds();
    var $t = $tracks();
    var $h = $hidden();
    var added = 0;

    $.each(recs, function (_, r) {
      var id = String(r.id);
      if (have[id]) { return; }
      have[id] = true;
      added++;

      var url = r.url || (CFG.ciPath + id);

      var $track = $(
        '<div class="track ci-pushed-row" data-ci-id="' + esc(id) + '">' +
          '<i class="ii icon-remove" title="Удалить" aria-label="Удалить ' + esc(r.label) +
            '" role="button" tabindex="0"></i>' +
          '<span class="item">' +
            '<a href="' + esc(url) + '" class=" previewlink" rel="preview" target="' +
              esc(url) + '/preview" title="' + esc(r.label) + '">' + esc(r.label) + '</a>' +
          '</span>' +
        '</div>'
      );

      var $inp = $('<input type="hidden" name="' + esc(name) + '" value="' + esc(id) +
                   '" data-ci-id="' + esc(id) + '">');

      $t.append($track);
      $h.append($inp);

      hardClick($track.find('i.icon-remove').get(0), function () {
        $track.remove();
        $inp.remove();
        syncTotal();
        if ($ext) { render(); }
      });
    });

    syncTotal();
    return { ok: true, how: name, added: added };
  }

  /* ---------------- списки ---------------- */

  function selectedIds() {
    var ids = {};
    $sel.find('.ci-item').each(function () { ids[String($(this).attr('data-id'))] = true; });
    return ids;
  }

  // никакой фильтрации — только прячем то, что уже выбрано/привязано
  function render() {
    var already = selectedIds();
    var attached = attachedIds();

    var rows = $.grep(pool, function (ci) {
      return !already[ci.id] && !attached[ci.id];
    });
    rows.sort(function (a, b) { return a.name.localeCompare(b.name, 'ru'); });

    $av.html($.map(rows, function (ci) {
      var s = ci.statusLabel ? ' — ' + ci.statusLabel : '';
      return itemHtml(ci.id, ci.name + s);
    }).join(''));
    counts();

    status('КЕ пользователя #' + pid + ': ' + rows.length, rows.length ? 'ok' : 'warn');
    message(rows.length ? 'Доступно КЕ: ' + rows.length : 'Подходящих КЕ не найдено',
            rows.length ? 'ok' : 'warn');
  }

  function moveRight() {
    var $items = $av.find('.ci-item.ci-sel');
    if (!$items.length) { message('Выделите строки в списке «Доступные КЕ»', 'warn'); return; }
    var already = selectedIds();
    $items.each(function () {
      var $i = $(this), id = String($i.attr('data-id'));
      if (!already[id]) { $sel.append(itemHtml(id, $i.text())); already[id] = true; }
      $i.remove();
    });
    sortList($sel);
    syncFields();
    counts();
    message('');
  }

  function moveLeft() {
    var $items = $sel.find('.ci-item.ci-sel');
    if (!$items.length) { message('Выделите строки в списке «Выбранные КЕ»', 'warn'); return; }
    $items.remove();
    syncFields();
    render();
  }

  /* ---------------- сохранение ---------------- */

  function syncFields() {
    var ids = [], names = [];
    $sel.find('.ci-item').each(function () {
      var $i = $(this);
      ids.push($i.attr('data-id'));
      names.push($i.text() + ' #' + $i.attr('data-id'));
    });
    $ext.find('#selected_ci_ids').val(ids.join(',')).trigger('change');
    $ext.find('#selected_cis').val(names.join('; ')).trigger('change');
    return ids;
  }

  function selectedRecords() {
    var out = [];
    $sel.find('.ci-item').each(function () {
      var $i = $(this), id = String($i.attr('data-id'));
      var src = null;
      $.each(pool, function (_, c) { if (c.id === id) { src = c; return false; } });
      out.push({
        id: id,
        label: (src && src.name) || $i.text(),
        url: (src && src.url) || (CFG.ciPath + id)
      });
    });
    return out;
  }

  function apply() {
    var recs = selectedRecords();
    if (!recs.length) { message('Список «Выбранные КЕ» пуст', 'warn'); return; }

    syncFields();
    var r = attachRows(recs);

    if (!r.ok) {
      message('Не удалось записать в штатное поле: ' + r.how, 'err');
      return;
    }

    $sel.empty();
    syncFields();
    render();

    message(r.added
      ? 'Добавлено в «Конфигурационные единицы»: ' + r.added + '. Сохраните запрос.'
      : 'Эти КЕ уже привязаны к запросу', r.added ? 'ok' : 'warn');
  }

  /* ---------------- восстановление ---------------- */

  function restore() {
    var raw = $ext.find('#selected_cis').val();
    if (!raw) { counts(); return; }
    var html = '';
    $.each(raw.split(';'), function (_, chunk) {
      var m = /^\s*(.+?)\s*#(\d+)\s*$/.exec(chunk);
      if (m) { html += itemHtml(m[2], m[1]); }
    });
    $sel.html(html);
    counts();
  }

  /* ---------------- init ---------------- */

  function init() {
    $ext = $('#ci_picker');
    if (!$ext.length || $ext.data('inited')) { return; }
    $ext.data('inited', true);

    $cat = $ext.find('#ci_category');
    $user = $ext.find('#ci_user');
    $av = $ext.find('.ci-available');
    $sel = $ext.find('.ci-selected');
    $st = $ext.find('.ci-status');
    $msg = $ext.find('.ci-msg');

    console.log(LOG + 'init ok, источник: ' + sourceId() + ' (' + sourceView() + ')');

    restore();
    syncUser();
    watchRequestedFor();

    // смена типа = другое представление = новый запрос
    $cat.on('change', function () {
      pool = [];
      $av.empty();
      counts();
      console.log(LOG + 'тип КЕ → ' + sourceId() + ' (' + sourceView() + ')');
      if (CFG.autoReload && pid) { load(); }
      else { message('Нажмите «Загрузить»'); }
    });

    $ext.on('click', '.ci-item', function () { $(this).toggleClass('ci-sel'); });
    $av.on('dblclick', '.ci-item', function () { $(this).addClass('ci-sel'); moveRight(); });
    $sel.on('dblclick', '.ci-item', function () { $(this).addClass('ci-sel'); moveLeft(); });

    $ext.find('.ci-load').on('click', load);
    $ext.find('.ci-to-right').on('click', moveRight);
    $ext.find('.ci-to-left').on('click', moveLeft);
    $ext.find('.ci-select-all').on('click', function () { $av.find('.ci-item').addClass('ci-sel'); });
    $ext.find('.ci-reset').on('click', function () {
      $av.find('.ci-item').removeClass('ci-sel');
      $sel.find('.ci-item').removeClass('ci-sel');
    });
    $ext.find('.ci-apply').on('click', apply);
  }

  init();
  $(init);
  setTimeout(init, 500);
  if (ITRP.hooks && ITRP.hooks.register) {
    ITRP.hooks.register('after-prefill', function () { init(); restore(); });
  }
})();
